{
  "name": "@berriai/litellm-agent-runtime",
  "version": "0.1.0-wave1",
  "description": "LiteLLM agent runtime daemon — coding-agent loop in the per-Session VM. Wave 1: scaffolding + tools + git/gh + single-run e2e.",
  "private": true,
  "type": "module",
  "bin": {
    "litellm-agent-runtime": "dist/index.js"
  },
  "main": "dist/index.js",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "format": "prettier --write \"src/**/*.ts\" \"tests/**/*.ts\"",
    "format:check": "prettier --check \"src/**/*.ts\" \"tests/**/*.ts\"",
    "test": "vitest run",
    "test:e2e": "vitest run tests/e2e",
    "test:unit": "vitest run tests/unit",
    "test:integration": "vitest run tests/integration",
    "start": "node dist/index.js"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^0.30.1",
    "undici": "^6.21.0"
  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "prettier": "^3.4.2",
    "typescript": "^5.6.3",
    "vitest": "^2.1.8"
  },
  "engines": {
    "node": ">=20.0.0"
  }
}

/**
 * Daemon -> proxy HTTP client.
 *
 * Wraps the four `/v2/sessions/{sid}/internal/...` endpoints defined in
 * `litellm/proxy/agent_session_endpoints/internal_endpoints.py`.
 *
 * All requests authenticate with a single session-scoped JWT (Bearer).
 */
import { request } from "undici";

import { log } from "../utils/logger.js";
import type {
  DaemonHeartbeatRequest,
  DaemonRegisterRequest,
  DaemonRegisterResponse,
  EventAppendRequest,
  EventAppendResponse,
  NextRunResponse,
} from "../types.js";

export class SessionTerminatedError extends Error {
  constructor(message = "Session terminated by proxy (HTTP 410)") {
    super(message);
    this.name = "SessionTerminatedError";
  }
}

export class ProxyHttpError extends Error {
  constructor(
    public readonly status: number,
    public readonly bodyText: string,
    message?: string,
  ) {
    super(message || `Proxy returned HTTP ${status}: ${bodyText.slice(0, 200)}`);
    this.name = "ProxyHttpError";
  }
}

export interface ProxyClientOptions {
  baseUrl: string;
  daemonJwt: string;
  sessionId: string;
  /** Per-request timeout (ms). Default 35s — slightly above the proxy's
   *  30s long-poll deadline. */
  defaultTimeoutMs?: number;
}

export class ProxyClient {
  private readonly baseUrl: string;
  private readonly jwt: string;
  private readonly sessionId: string;
  private readonly timeoutMs: number;

  constructor(opts: ProxyClientOptions) {
    this.baseUrl = opts.baseUrl.replace(/\/+$/, "");
    this.jwt = opts.daemonJwt;
    this.sessionId = opts.sessionId;
    this.timeoutMs = opts.defaultTimeoutMs ?? 35_000;
  }

  private url(path: string): string {
    return `${this.baseUrl}${path}`;
  }

  private headers(): Record<string, string> {
    return {
      authorization: `Bearer ${this.jwt}`,
      "content-type": "application/json",
    };
  }

  /**
   * Issue an HTTP request and parse JSON. On 410 throws SessionTerminatedError;
   * on 204 returns null; on any other non-2xx throws ProxyHttpError.
   */
  private async send<T>(
    method: "GET" | "POST",
    path: string,
    body?: unknown,
    timeoutMs?: number,
  ): Promise<T | null> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs ?? this.timeoutMs);
    try {
      const res = await request(this.url(path), {
        method,
        headers: this.headers(),
        body: body !== undefined ? JSON.stringify(body) : undefined,
        signal: controller.signal,
      });

      if (res.statusCode === 410) {
        throw new SessionTerminatedError();
      }
      if (res.statusCode === 204) {
        // Drain body so the connection can be reused.
        await res.body.text();
        return null;
      }
      const text = await res.body.text();
      if (res.statusCode >= 200 && res.statusCode < 300) {
        if (!text) return null;
        return JSON.parse(text) as T;
      }
      throw new ProxyHttpError(res.statusCode, text);
    } finally {
      clearTimeout(timer);
    }
  }

  /** POST /v2/sessions/{sid}/internal/register */
  async register(body: DaemonRegisterRequest): Promise<DaemonRegisterResponse> {
    const result = await this.send<DaemonRegisterResponse>(
      "POST",
      `/v2/sessions/${this.sessionId}/internal/register`,
      body,
    );
    if (!result) {
      throw new Error("register: proxy returned no body");
    }
    log.info("session.registered", {
      sessionId: this.sessionId,
      status: result.status,
    });
    return result;
  }

  /** POST /v2/sessions/{sid}/internal/heartbeat */
  async heartbeat(body: DaemonHeartbeatRequest = {}): Promise<void> {
    await this.send(
      "POST",
      `/v2/sessions/${this.sessionId}/internal/heartbeat`,
      body,
      10_000,
    );
  }

  /**
   * GET /v2/sessions/{sid}/runs/next/internal/poll  (long-poll, ~30s)
   * Returns null if no run was queued before the deadline.
   */
  async pollNextRun(): Promise<NextRunResponse | null> {
    return this.send<NextRunResponse>(
      "GET",
      `/v2/sessions/${this.sessionId}/runs/next/internal/poll`,
      undefined,
      // The proxy itself caps at 30s; allow a small overhead for network.
      35_000,
    );
  }

  /** POST /v2/sessions/{sid}/runs/{rid}/events:append */
  async appendEvent(
    runId: string,
    body: EventAppendRequest,
  ): Promise<EventAppendResponse> {
    const result = await this.send<EventAppendResponse>(
      "POST",
      `/v2/sessions/${this.sessionId}/runs/${runId}/events:append`,
      body,
      10_000,
    );
    if (!result) {
      throw new Error(`appendEvent(${runId}): proxy returned no body`);
    }
    return result;
  }
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: false,
    environment: "node",
    include: ["tests/**/*.test.ts"],
    testTimeout: 60_000,
    hookTimeout: 30_000,
  },
});

/**
 * Shared types — wire shapes match the proxy's pydantic schemas in
 * `litellm/proxy/agent_session_endpoints/schemas.py`.
 *
 * Keep field names and types stable once shipped; the TS SDK (Epic D)
 * may codegen types from this file.
 */

// ---------------------------------------------------------------------------
// Daemon runtime config (read from env / systemd EnvironmentFile)
// ---------------------------------------------------------------------------

export type DaemonMode = "session" | "warm";

export interface DaemonRuntimeConfig {
  /** Base URL of the LiteLLM proxy, no trailing slash. */
  baseUrl: string;
  /** Session-scoped JWT minted at session create. */
  daemonJwt: string;
  /** Session ID this daemon owns (the daemon serves exactly one Session). */
  sessionId: string;
  /** "session" = cold-boot path, "warm" = warm-pool idle path (B2). */
  mode: DaemonMode;
  /** Optional VM ID — passed back to the proxy on register/heartbeat. */
  vmId?: string;
  /** Daemon version string for register payload. */
  daemonVersion: string;
  /** Workspace root where repos get cloned. Default: /workspace */
  workspaceRoot: string;
  /** Path to write secrets file (mode 0600 root-only). */
  secretsFile: string;
}

// ---------------------------------------------------------------------------
// Hydrate payload (returned by /v2/sessions/{sid}/internal/register, or
// pushed via SSM in warm mode). The daemon reads this at session start.
// ---------------------------------------------------------------------------

export interface RepoSpec {
  url: string;
  startingRef?: string | null;
  /** Optional auth header for clone. */
  cloneAuthHeader?: string;
}

export interface AgentConfig {
  model?: string;
  systemPrompt?: string;
  /** If true, daemon will `gh pr create` at the end of any run that
   *  produced a non-empty diff. Generic flag — used by shin-cursor and
   *  any other customer that wants auto-PR. */
  autoCreatePr?: boolean;
  /** Optional max iterations for the inner agent loop. Default 25. */
  maxIterations?: number;
}

export interface HydratePayload {
  sessionId: string;
  repos: RepoSpec[];
  envVars: Record<string, string>;
  /** Sensitive secrets — written to secretsFile, NOT logged. */
  secrets: Record<string, string>;
  /** Network allowlist (Wave 3 / Layer 2 extension point). */
  networkAccess?: { allowedDomains: string[] };
  agentConfig: AgentConfig;
}

// ---------------------------------------------------------------------------
// Proxy wire types (mirror schemas.py)
// ---------------------------------------------------------------------------

export interface DaemonRegisterRequest {
  vm_id?: string;
  daemon_version?: string;
}

export interface DaemonRegisterResponse {
  session_id: string;
  status: string;
  registered_at: string;
}

export interface DaemonHeartbeatRequest {
  vm_id?: string;
}

export interface NextRunResponse {
  run_id: string;
  prompt: Record<string, unknown>;
}

export interface EventAppendRequest {
  event_type: string;
  payload: Record<string, unknown>;
}

export interface EventAppendResponse {
  run_id: string;
  seq: number;
  event_type: string;
}

// ---------------------------------------------------------------------------
// Run-loop event types (matched against
// `litellm/proxy/agent_session_endpoints/constants.py`)
// ---------------------------------------------------------------------------

export const EVENT_TYPES = {
  RUN_STARTED: "run_started",
  RUN_FINISHED: "run_finished",
  RUN_CANCELLED: "run_cancelled",
  RUN_ERROR: "run_error",
  USER_MESSAGE: "user_message",
  ASSISTANT_MESSAGE: "assistant_message",
  TOOL_CALL: "tool_call",
  TOOL_RESULT: "tool_result",
  TERMINAL_CHUNK: "terminal_chunk",
  FILE_DIFF: "file_diff",
  STATUS_SUMMARY: "status_summary",
  GIT_COMMIT: "git_commit",
  PR_OPENED: "pr_opened",
} as const;

export type EventType = (typeof EVENT_TYPES)[keyof typeof EVENT_TYPES];

// ---------------------------------------------------------------------------
// Tool framework
// ---------------------------------------------------------------------------

/** A tool definition in Anthropic-compatible JSON Schema format. */
export interface ToolDefinition {
  name: string;
  description: string;
  input_schema: {
    type: "object";
    properties: Record<string, unknown>;
    required?: string[];
    additionalProperties?: boolean;
  };
}

export interface ToolExecutionContext {
  workspaceRoot: string;
  /** Emit terminal_chunk / file_diff / etc. events while a tool runs. */
  emit: (eventType: EventType, payload: Record<string, unknown>) => Promise<void>;
}

export interface ToolResult {
  /** Stringified content the LLM sees back. */
  content: string;
  isError?: boolean;
}

export type ToolHandler = (
  input: Record<string, unknown>,
  ctx: ToolExecutionContext,
) => Promise<ToolResult>;

export interface ToolRegistration {
  definition: ToolDefinition;
  handler: ToolHandler;
}

/**
 * Tool registry — gathers all tool registrations into a single map keyed
 * by tool name. Layer-1 / Layer-3 extensions (skills, MCP) can later
 * inject additional tools by passing a custom registry to the run loop.
 */
import { globTool } from "./glob.js";
import { grepTool } from "./grep.js";
import { readFileTool } from "./read_file.js";
import { shellTool } from "./shell.js";
import { strReplaceTool } from "./str_replace.js";
import { makeTodoTool } from "./todo.js";
import type { TodoStore } from "./todo.js";
import type { ToolDefinition, ToolRegistration } from "../types.js";

export interface BuildToolsOptions {
  /** Per-run mutable state for the `todo` tool. */
  todoStore: TodoStore;
  /** Additional tools (e.g. from .cursor/mcp.json — Wave 2). */
  extra?: ToolRegistration[];
}

export function buildTools(opts: BuildToolsOptions): Map<string, ToolRegistration> {
  const all: ToolRegistration[] = [
    readFileTool,
    strReplaceTool,
    shellTool,
    grepTool,
    globTool,
    makeTodoTool(opts.todoStore),
    ...(opts.extra || []),
  ];
  const map = new Map<string, ToolRegistration>();
  for (const t of all) {
    if (map.has(t.definition.name)) {
      throw new Error(`Duplicate tool name: ${t.definition.name}`);
    }
    map.set(t.definition.name, t);
  }
  return map;
}

export function toolDefinitions(map: Map<string, ToolRegistration>): ToolDefinition[] {
  return Array.from(map.values()).map((t) => t.definition);
}

/**
 * glob — list files matching a glob pattern, sorted by mtime desc.
 *
 * Mirrors Cursor's `glob_file_search`. Uses a simple shell-out to `find`
 * + sort to avoid pulling in a glob library — the result feeds the LLM
 * which only needs paths, and `find` is universally available.
 */
import type { ToolHandler, ToolRegistration } from "../types.js";
import { resolveSafePath, runShell } from "./shell.js";

const MAX_HITS = 200;

/** Convert a `**` / `*` glob into a regex that matches relative paths. */
function globToRegex(pattern: string): string {
  let out = "^";
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "*") {
      if (pattern[i + 1] === "*") {
        out += ".*";
        i++;
        if (pattern[i + 1] === "/") i++;
      } else {
        out += "[^/]*";
      }
    } else if (c === "?") {
      out += "[^/]";
    } else if (c === ".") {
      out += "\\.";
    } else if (c === "/") {
      out += "/";
    } else if (/[a-zA-Z0-9_\-]/.test(c!)) {
      out += c;
    } else {
      out += "\\" + c;
    }
  }
  out += "$";
  return out;
}

const handler: ToolHandler = async (input, ctx) => {
  const pattern = String(input.pattern || "");
  if (!pattern) {
    return { content: "Error: 'pattern' is required.", isError: true };
  }
  const cwd =
    typeof input.path === "string" && input.path
      ? resolveSafePath(ctx.workspaceRoot, input.path)
      : ctx.workspaceRoot;

  const regex = globToRegex(pattern);
  // List files (-type f) and pipe through grep -E to filter by glob-as-regex.
  const cmd = `find . -type f -not -path '*/.git/*' -not -path '*/node_modules/*' | sed 's|^\\./||' | grep -E ${JSON.stringify(regex)} | head -n ${MAX_HITS}`;
  const res = await runShell(cmd, { cwd, timeoutMs: 30_000 });
  const hits = res.stdout.trim();
  if (!hits) {
    return { content: `No files match '${pattern}'.` };
  }
  return { content: hits };
};

export const globTool: ToolRegistration = {
  definition: {
    name: "glob",
    description:
      "Find files matching a glob pattern (e.g. '**/*.ts', 'src/**/*.tsx'). " +
      "Returns up to 200 matching paths.",
    input_schema: {
      type: "object",
      properties: {
        pattern: {
          type: "string",
          description: "Glob pattern. `**` matches any directories, `*` matches any filename chars.",
        },
        path: {
          type: "string",
          description: "Subdirectory to search in (relative to workspace root).",
        },
      },
      required: ["pattern"],
      additionalProperties: false,
    },
  },
  handler,
};

/**
 * Read daemon runtime config from env (set by systemd EnvironmentFile or
 * the test harness). Fail loudly with actionable messages if anything
 * required is missing.
 */
import type { DaemonMode, DaemonRuntimeConfig } from "../types.js";

const DAEMON_VERSION = "0.1.0-wave1";

function require_env(key: string): string {
  const v = process.env[key];
  if (!v) {
    throw new Error(
      `${key} is not set. The daemon requires this env var. ` +
        `It is normally provisioned by EC2 user-data via the systemd EnvironmentFile ` +
        `at /etc/litellm-agent/runtime.env.`,
    );
  }
  return v;
}

export function loadRuntimeConfig(): DaemonRuntimeConfig {
  const modeRaw = (process.env.LITELLM_AGENT_MODE || "session").toLowerCase();
  if (modeRaw !== "session" && modeRaw !== "warm") {
    throw new Error(
      `LITELLM_AGENT_MODE must be 'session' or 'warm', got '${modeRaw}'.`,
    );
  }
  const mode: DaemonMode = modeRaw;

  const baseUrlRaw = require_env("LITELLM_BASE_URL").replace(/\/+$/, "");
  const daemonJwt = require_env("LITELLM_DAEMON_JWT");

  // In warm mode the session id is unknown until hydrate; allow empty.
  const sessionId =
    mode === "warm"
      ? process.env.LITELLM_SESSION_ID || ""
      : require_env("LITELLM_SESSION_ID");

  return {
    baseUrl: baseUrlRaw,
    daemonJwt,
    sessionId,
    mode,
    vmId: process.env.LITELLM_VM_ID || undefined,
    daemonVersion: DAEMON_VERSION,
    workspaceRoot: process.env.LITELLM_WORKSPACE_ROOT || "/workspace",
    secretsFile: process.env.LITELLM_SECRETS_FILE || "/etc/litellm-agent/secrets.env",
  };
}

/**
 * EventEmitter — pushes run events to the proxy via append-event.
 *
 * Serializes appends per (sessionId, runId) so seq numbers are monotonic.
 * The proxy assigns the actual seq, but if we emit in parallel we'd cause
 * (recoverable but noisy) seq collisions. Single in-flight append per run
 * is simpler and correct.
 */
import { ProxyClient } from "../client/api.js";
import { log } from "../utils/logger.js";
import type { EventType } from "../types.js";

export class EventEmitter {
  private chain: Promise<void> = Promise.resolve();

  constructor(
    private readonly client: ProxyClient,
    private readonly runId: string,
  ) {}

  /**
   * Append an event. Returns when the append completes.
   *
   * Errors are logged and swallowed for non-terminal events (we don't
   * want a transient network blip to abort the run loop). Terminal
   * events (run_finished/run_error/run_cancelled) re-throw so the
   * caller can decide whether to retry.
   */
  async emit(eventType: EventType, payload: Record<string, unknown>): Promise<void> {
    const isTerminal =
      eventType === "run_finished" ||
      eventType === "run_error" ||
      eventType === "run_cancelled";

    const job = this.chain.then(async () => {
      try {
        await this.client.appendEvent(this.runId, {
          event_type: eventType,
          payload,
        });
      } catch (err) {
        log.warn("event.append.failed", {
          runId: this.runId,
          eventType,
          err: String(err),
        });
        if (isTerminal) {
          throw err;
        }
      }
    });
    this.chain = job.catch(() => undefined);
    return job;
  }
}

/**
 * Tiny structured logger. Prints JSON lines to stdout for easy ingestion
 * by CloudWatch / journalctl. No third-party dep.
 */

type Level = "debug" | "info" | "warn" | "error";

const LEVEL_ORDER: Record<Level, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

function currentLevel(): Level {
  const raw = (process.env.LITELLM_AGENT_LOG_LEVEL || "info").toLowerCase();
  if (raw === "debug" || raw === "info" || raw === "warn" || raw === "error") {
    return raw;
  }
  return "info";
}

function emit(level: Level, msg: string, fields?: Record<string, unknown>): void {
  if (LEVEL_ORDER[level] < LEVEL_ORDER[currentLevel()]) return;
  const line = JSON.stringify({
    ts: new Date().toISOString(),
    level,
    msg,
    ...(fields || {}),
  });
  // stderr for warn/error so they're visible separately in journalctl.
  if (level === "warn" || level === "error") {
    process.stderr.write(line + "\n");
  } else {
    process.stdout.write(line + "\n");
  }
}

export const log = {
  debug: (msg: string, fields?: Record<string, unknown>) => emit("debug", msg, fields),
  info: (msg: string, fields?: Record<string, unknown>) => emit("info", msg, fields),
  warn: (msg: string, fields?: Record<string, unknown>) => emit("warn", msg, fields),
  error: (msg: string, fields?: Record<string, unknown>) => emit("error", msg, fields),
};

/** Redact a secret-ish string for logging. */
export function redact(value: string | undefined | null): string {
  if (!value) return "<unset>";
  if (value.length <= 8) return "***";
  return `${value.slice(0, 4)}...${value.slice(-4)}`;
}

/**
 * todo — manage a per-run task list.
 *
 * Mirrors Cursor's `todo_write`. State is held on the run loop instance
 * (passed in via context.todos), not on disk. The model uses this to
 * keep itself organized over a long run.
 */
import type { ToolHandler, ToolRegistration } from "../types.js";

export type TodoStatus = "pending" | "in_progress" | "completed";

export interface TodoItem {
  id: string;
  content: string;
  status: TodoStatus;
}

export interface TodoStore {
  items: TodoItem[];
}

/** Build the todo tool, capturing a per-run mutable store. */
export function makeTodoTool(store: TodoStore): ToolRegistration {
  const handler: ToolHandler = async (input) => {
    const merge = Boolean(input.merge);
    const incoming = Array.isArray(input.todos) ? input.todos : [];
    const validated: TodoItem[] = [];
    for (const raw of incoming) {
      if (typeof raw !== "object" || raw === null) continue;
      const obj = raw as Record<string, unknown>;
      const id = typeof obj.id === "string" && obj.id ? obj.id : `t${validated.length + 1}`;
      const content = typeof obj.content === "string" ? obj.content : "";
      const status =
        obj.status === "pending" || obj.status === "in_progress" || obj.status === "completed"
          ? obj.status
          : "pending";
      if (!content) continue;
      validated.push({ id, content, status });
    }

    if (merge) {
      const byId = new Map<string, TodoItem>(store.items.map((t) => [t.id, t]));
      for (const t of validated) byId.set(t.id, t);
      store.items = Array.from(byId.values());
    } else {
      store.items = validated;
    }

    const summary = store.items
      .map((t) => {
        const box = t.status === "completed" ? "[x]" : t.status === "in_progress" ? "[~]" : "[ ]";
        return `${box} ${t.id}: ${t.content}`;
      })
      .join("\n");
    return { content: summary || "(no todos)" };
  };

  return {
    definition: {
      name: "todo",
      description:
        "Maintain a per-run TODO list to track multi-step work. Pass the " +
        "full new list (default) or set merge=true to upsert by id. Status " +
        "must be one of pending|in_progress|completed.",
      input_schema: {
        type: "object",
        properties: {
          todos: {
            type: "array",
            items: {
              type: "object",
              properties: {
                id: { type: "string" },
                content: { type: "string" },
                status: {
                  type: "string",
                  enum: ["pending", "in_progress", "completed"],
                },
              },
              required: ["content"],
            },
          },
          merge: {
            type: "boolean",
            description: "If true, upsert by id rather than replacing the whole list.",
          },
        },
        required: ["todos"],
        additionalProperties: false,
      },
    },
    handler,
  };
}

/**
 * grep — recursive content search using ripgrep when available, with a
 * grep fallback for environments where rg isn't installed.
 *
 * Mirrors Cursor's `grep` tool. Returns a list of "path:line:match" hits
 * up to a sensible cap.
 */
import type { ToolHandler, ToolRegistration } from "../types.js";
import { resolveSafePath, runShell } from "./shell.js";

const MAX_HITS = 200;

const handler: ToolHandler = async (input, ctx) => {
  const pattern = String(input.pattern || "");
  if (!pattern) {
    return { content: "Error: 'pattern' is required.", isError: true };
  }
  const include = typeof input.include === "string" ? input.include : "";
  const cwd =
    typeof input.path === "string" && input.path
      ? resolveSafePath(ctx.workspaceRoot, input.path)
      : ctx.workspaceRoot;

  // Prefer rg; fall back to grep -R. Use --no-color and -n for line numbers.
  // Quote the pattern to avoid shell expansion.
  const escapedPattern = pattern.replace(/'/g, `'\\''`);
  const includeArg = include ? ` -g '${include.replace(/'/g, `'\\''`)}'` : "";
  const rgCmd = `rg -n --no-heading --no-color${includeArg} -- '${escapedPattern}' . | head -n ${MAX_HITS}`;
  const rgRes = await runShell(rgCmd, { cwd, timeoutMs: 30_000 });

  let hits: string;
  if (rgRes.exitCode === 0 || rgRes.exitCode === 1) {
    hits = rgRes.stdout.trim();
  } else {
    // ripgrep absent or errored — try grep.
    const grepIncludeArg = include ? ` --include='${include.replace(/'/g, `'\\''`)}'` : "";
    const grepCmd = `grep -RnI${grepIncludeArg} -- '${escapedPattern}' . | head -n ${MAX_HITS}`;
    const grepRes = await runShell(grepCmd, { cwd, timeoutMs: 30_000 });
    hits = grepRes.stdout.trim();
  }

  if (!hits) {
    return { content: `No matches for /${pattern}/.` };
  }
  return { content: hits };
};

