/**
 * git clone helper. The daemon runs as root inside the VM with a
 * forwarded `SHIN_GITHUB_TOKEN` (or any other secret named via the
 * hydrate payload) — we inject that into the clone URL so the daemon
 * has push access to private repos.
 *
 * Mode of operation:
 *   1. Build a URL with embedded token if `cloneAuthHeader` is set.
 *   2. Run `git clone --depth=50 <url> <dest>`.
 *   3. If `startingRef` is given, `git -C <dest> checkout <ref>`.
 */
import path from "node:path";
import { promises as fs } from "node:fs";

import type { RepoSpec } from "../types.js";
import { log } from "../utils/logger.js";
import { runShell } from "../tools/shell.js";

export interface CloneResult {
  /** Local absolute path of the cloned repo. */
  path: string;
  /** Repo basename derived from the URL (e.g. `litellm-agent-test-target`). */
  name: string;
  /** Branch / ref currently checked out. */
  ref: string;
}

function deriveRepoName(url: string): string {
  const stripped = url.replace(/\.git$/, "");
  const parts = stripped.split(/[/:]/).filter(Boolean);
  return parts[parts.length - 1] || "repo";
}

function buildAuthedUrl(rawUrl: string, token: string | undefined): string {
  if (!token) return rawUrl;
  // Only inject for https URLs. SSH URLs need keys, not bearer tokens.
  if (!rawUrl.startsWith("https://")) return rawUrl;
  return rawUrl.replace(/^https:\/\//, `https://x-access-token:${token}@`);
}

/**
 * Clone `repo` into `<workspaceRoot>/<repoName>`. If the directory
 * already exists, return its info without re-cloning (multi-run within
 * a Session: workspace is preserved between runs).
 */
export async function cloneRepo(
  workspaceRoot: string,
  repo: RepoSpec,
): Promise<CloneResult> {
  const name = deriveRepoName(repo.url);
  const dest = path.join(workspaceRoot, name);

  // Idempotency: if the directory exists with a .git inside, treat as
  // already cloned. The agent loop is responsible for fetching and
  // moving HEAD; we don't blow away local edits.
  try {
    await fs.access(path.join(dest, ".git"));
    log.info("git.clone.skipped_existing", { name, dest });
    const refRes = await runShell("git rev-parse --abbrev-ref HEAD", {
      cwd: dest,
      timeoutMs: 5_000,
    });
    return { path: dest, name, ref: refRes.stdout.trim() || "HEAD" };
  } catch {
    // not yet cloned — fall through
  }

  await fs.mkdir(workspaceRoot, { recursive: true });

  const url = buildAuthedUrl(repo.url, repo.cloneAuthHeader);
  const cloneCmd = `git clone --depth=50 ${JSON.stringify(url)} ${JSON.stringify(dest)}`;
  const cloneRes = await runShell(cloneCmd, {
    cwd: workspaceRoot,
    timeoutMs: 180_000,
  });
  if (cloneRes.exitCode !== 0) {
    throw new Error(
      `git clone failed (exit ${cloneRes.exitCode}): ${cloneRes.stderr.slice(0, 500)}`,
    );
  }

  let ref = "HEAD";
  if (repo.startingRef) {
    const co = await runShell(
      `git fetch --depth=50 origin ${JSON.stringify(repo.startingRef)} && git checkout ${JSON.stringify(repo.startingRef)}`,
      { cwd: dest, timeoutMs: 60_000 },
    );
    if (co.exitCode !== 0) {
      throw new Error(
        `git checkout ${repo.startingRef} failed: ${co.stderr.slice(0, 500)}`,
      );
    }
    ref = repo.startingRef;
  } else {
    const refRes = await runShell("git rev-parse --abbrev-ref HEAD", {
      cwd: dest,
      timeoutMs: 5_000,
    });
    ref = refRes.stdout.trim() || "HEAD";
  }

  log.info("git.clone.done", { name, dest, ref });
  return { path: dest, name, ref };
}

/**
 * read_file — read a file from the workspace.
 *
 * Mirrors Cursor's `read_file` tool. Optional offset/limit (1-indexed lines)
 * for paging through large files. Returns content or an error string the
 * LLM can recover from (don't throw for "file not found" — let the model
 * react).
 */
import { promises as fs } from "node:fs";
import path from "node:path";

import type { ToolHandler, ToolRegistration } from "../types.js";
import { resolveSafePath } from "./shell.js";

const MAX_BYTES = 256 * 1024; // 256 KiB safety cap.

const handler: ToolHandler = async (input, ctx) => {
  const filePath = String(input.path || "");
  if (!filePath) {
    return { content: "Error: 'path' is required.", isError: true };
  }
  const offset = typeof input.offset === "number" ? Math.max(1, input.offset) : 1;
  const limit = typeof input.limit === "number" ? Math.max(1, input.limit) : undefined;

  let abs: string;
  try {
    abs = resolveSafePath(ctx.workspaceRoot, filePath);
  } catch (err) {
    return { content: `Error: ${(err as Error).message}`, isError: true };
  }

  let buf: Buffer;
  try {
    buf = await fs.readFile(abs);
  } catch (err) {
    return {
      content: `Error reading ${path.relative(ctx.workspaceRoot, abs)}: ${(err as Error).message}`,
      isError: true,
    };
  }

  if (buf.length > MAX_BYTES && offset === 1 && limit === undefined) {
    return {
      content:
        `Error: file too large (${buf.length} bytes > ${MAX_BYTES}). ` +
        `Pass offset+limit to page through it.`,
      isError: true,
    };
  }

  const text = buf.toString("utf8");
  const lines = text.split(/\r?\n/);
  const start = offset - 1;
  const end = limit !== undefined ? start + limit : lines.length;
  const slice = lines.slice(start, end);
  return {
    content: slice.map((l, i) => `${start + i + 1}\t${l}`).join("\n"),
  };
};

export const readFileTool: ToolRegistration = {
  definition: {
    name: "read_file",
    description:
      "Read a UTF-8 text file from the workspace. Returns the file's contents " +
      "with 1-indexed line-number prefixes (`<lineNum>\\t<content>`). For " +
      "large files use `offset` + `limit` to read a slice.",
    input_schema: {
      type: "object",
      properties: {
        path: {
          type: "string",
          description: "Path relative to the workspace root.",
        },
        offset: {
          type: "integer",
          description: "1-indexed starting line.",
          minimum: 1,
        },
        limit: {
          type: "integer",
          description: "Max number of lines to read.",
          minimum: 1,
        },
      },
      required: ["path"],
      additionalProperties: false,
    },
  },
  handler,
};

/**
 * str_replace — exact-string replacement edit.
 *
 * Mirrors Cursor's / Anthropic's `str_replace_editor` semantics: the
 * `old_string` MUST appear exactly once in the file. If it doesn't, we
 * return an error so the model can re-read and try again. Emits a
 * `file_diff` event with +N -M counts after a successful edit.
 */
import { promises as fs } from "node:fs";
import path from "node:path";

import type { ToolHandler, ToolRegistration } from "../types.js";
import { resolveSafePath } from "./shell.js";

function countLineChanges(
  before: string,
  after: string,
): { added: number; removed: number } {
  // Quick + accurate enough: we count lines that differ between the two
  // strings without computing a full LCS diff. This is reported to the
  // proxy as a `file_diff` event for UI display, not used for any logic.
  const beforeLines = before.split(/\r?\n/);
  const afterLines = after.split(/\r?\n/);
  return {
    added: Math.max(0, afterLines.length - beforeLines.length),
    removed: Math.max(0, beforeLines.length - afterLines.length),
  };
}

const handler: ToolHandler = async (input, ctx) => {
  const filePath = String(input.path || "");
  const oldString = typeof input.old_string === "string" ? input.old_string : "";
  const newString = typeof input.new_string === "string" ? input.new_string : "";
  const create = Boolean(input.create);

  if (!filePath) {
    return { content: "Error: 'path' is required.", isError: true };
  }

  let abs: string;
  try {
    abs = resolveSafePath(ctx.workspaceRoot, filePath);
  } catch (err) {
    return { content: `Error: ${(err as Error).message}`, isError: true };
  }

  let exists = true;
  let original = "";
  try {
    original = await fs.readFile(abs, "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      exists = false;
    } else {
      return {
        content: `Error reading ${path.relative(ctx.workspaceRoot, abs)}: ${(err as Error).message}`,
        isError: true,
      };
    }
  }

  let next: string;
  if (!exists) {
    if (!create) {
      return {
        content: `Error: file ${filePath} does not exist. Pass create=true to create it.`,
        isError: true,
      };
    }
    if (oldString !== "") {
      return {
        content: "Error: when create=true, old_string must be empty.",
        isError: true,
      };
    }
    await fs.mkdir(path.dirname(abs), { recursive: true });
    next = newString;
  } else {
    if (oldString === "") {
      return {
        content:
          "Error: 'old_string' is required for an existing file. To overwrite from scratch, " +
          "delete the file first via shell, then re-create with create=true.",
        isError: true,
      };
    }
    const occurrences = original.split(oldString).length - 1;
    if (occurrences === 0) {
      return {
        content:
          `Error: 'old_string' not found in ${filePath}. Re-read the file and ` +
          `pass an exact byte-for-byte match (including indentation).`,
        isError: true,
      };
    }
    if (occurrences > 1) {
      return {
        content:
          `Error: 'old_string' matched ${occurrences} times in ${filePath}. ` +
          `Add more surrounding context so the match is unique.`,
        isError: true,
      };
    }
    next = original.replace(oldString, newString);
  }

  await fs.writeFile(abs, next, "utf8");

  const diff = countLineChanges(original, next);
  await ctx.emit("file_diff", {
    path: path.relative(ctx.workspaceRoot, abs),
    added: diff.added,
    removed: diff.removed,
    created: !exists,
  });

  return {
    content: !exists
      ? `Created ${filePath}.`
      : `Edited ${filePath} (+${diff.added} -${diff.removed}).`,
  };
};

export const strReplaceTool: ToolRegistration = {
  definition: {
    name: "str_replace",
    description:
      "Replace the unique occurrence of `old_string` with `new_string` in a " +
      "file. The `old_string` must match exactly once — include enough " +
      "surrounding context to be unique. Pass `create=true` with an empty " +
      "`old_string` to create a new file with `new_string` as its content.",
    input_schema: {
      type: "object",
      properties: {
        path: { type: "string", description: "Path relative to workspace root." },
        old_string: { type: "string" },
        new_string: { type: "string" },
        create: {
          type: "boolean",
          description: "If true, create the file with `new_string` as content.",
        },
      },
      required: ["path", "new_string"],
      additionalProperties: false,
    },
  },
  handler,
};

/**
 * shell — run a bash command in the workspace.
 *
 * Mirrors Cursor's `run_terminal_cmd`. Streams stdout+stderr as
 * `terminal_chunk` events so the UI can render live output. Default
 * timeout 120s; override via the `timeout_ms` arg.
 */
import { spawn } from "node:child_process";
import path from "node:path";

import type { ToolHandler, ToolRegistration } from "../types.js";

const DEFAULT_TIMEOUT_MS = 120_000;
const MAX_OUTPUT_BYTES = 256 * 1024; // 256 KiB cap for the LLM-visible result.

/**
 * Resolve `relPath` inside `workspaceRoot`, refusing to escape the workspace.
 * Throws if `relPath` is absolute or contains `..` traversal that lands outside.
 */
export function resolveSafePath(workspaceRoot: string, relPath: string): string {
  const root = path.resolve(workspaceRoot);
  const candidate = path.resolve(root, relPath);
  if (candidate !== root && !candidate.startsWith(root + path.sep)) {
    throw new Error(
      `path '${relPath}' escapes workspace root '${workspaceRoot}'`,
    );
  }
  return candidate;
}

interface ShellRunResult {
  exitCode: number | null;
  stdout: string;
  stderr: string;
  timedOut: boolean;
}

export interface RunShellOptions {
  cwd: string;
  timeoutMs: number;
  /** Called with each chunk of stdout/stderr. */
  onChunk?: (stream: "stdout" | "stderr", chunk: string) => void;
  /** Optional env overrides (merged on top of process.env). */
  env?: Record<string, string>;
}

/**
 * Spawn `bash -lc <command>` and capture output. Pure helper — no events,
 * no proxy traffic. Used by the tool wrapper below and by `git/` helpers.
 */
export async function runShell(
  command: string,
  opts: RunShellOptions,
): Promise<ShellRunResult> {
  return new Promise((resolve) => {
    const child = spawn("bash", ["-lc", command], {
      cwd: opts.cwd,
      env: { ...process.env, ...(opts.env || {}) },
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let timedOut = false;

    const timer = setTimeout(() => {
      timedOut = true;
      child.kill("SIGKILL");
    }, opts.timeoutMs);

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (data: string) => {
      stdout += data;
      opts.onChunk?.("stdout", data);
    });
    child.stderr.on("data", (data: string) => {
      stderr += data;
      opts.onChunk?.("stderr", data);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ exitCode: code, stdout, stderr, timedOut });
    });
    child.on("error", (err) => {
      clearTimeout(timer);
      resolve({
        exitCode: null,
        stdout,
        stderr: stderr + `\n[spawn error] ${err.message}`,
        timedOut,
      });
    });
  });
}

function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return text.slice(0, max) + `\n[... truncated ${text.length - max} bytes ...]`;
}

const handler: ToolHandler = async (input, ctx) => {
  const command = String(input.command || "");
  if (!command) {
    return { content: "Error: 'command' is required.", isError: true };
  }
  const timeoutMs =
    typeof input.timeout_ms === "number" && input.timeout_ms > 0
      ? Math.min(600_000, input.timeout_ms)
      : DEFAULT_TIMEOUT_MS;

  const cwd =
    typeof input.cwd === "string" && input.cwd
      ? resolveSafePath(ctx.workspaceRoot, input.cwd)
      : ctx.workspaceRoot;

  const result = await runShell(command, {
    cwd,
    timeoutMs,
    onChunk: (stream, chunk) => {
      // Fire and forget — emitter serializes anyway.
      void ctx.emit("terminal_chunk", { stream, chunk });
    },
  });

  const summary = [
    `exit_code: ${result.exitCode}${result.timedOut ? " (TIMED OUT)" : ""}`,
    "--- stdout ---",
    truncate(result.stdout, MAX_OUTPUT_BYTES / 2),
    "--- stderr ---",
    truncate(result.stderr, MAX_OUTPUT_BYTES / 2),
  ].join("\n");

  return {
    content: summary,
    isError: result.exitCode !== 0,
  };
};

export const shellTool: ToolRegistration = {
  definition: {
    name: "shell",
    description:
      "Execute a bash command in the workspace. Stdout and stderr are " +
      "streamed back as `terminal_chunk` events. Default cwd is the " +
      "workspace root. Use this for git, tests, builds, package managers, " +
      "and any operation not covered by a dedicated tool.",
    input_schema: {
      type: "object",
      properties: {
        command: {
          type: "string",
          description: "Bash command to run.",
        },
        cwd: {
          type: "string",
          description: "Working directory relative to workspace. Defaults to workspace root.",
        },
        timeout_ms: {
          type: "integer",
          description: "Max runtime in ms (default 120000, max 600000).",
          minimum: 1,
        },
      },
      required: ["command"],
      additionalProperties: false,
    },
  },
  handler,
};
